sys_variable_value.value:
(function execute(inputs, outputs) {

    var decisionInputs = {};

    decisionInputs['u_claim_type'] =
        String(inputs.claim_type).toLowerCase();

    decisionInputs['u_fraud_risk'] =
        String(inputs.fraud_risk).toLowerCase();

    decisionInputs['u_coverage_amount_numeric'] =
        inputs.coverage_amount_numeric;

    decisionInputs['u_claim_amount_numeric'] =
        inputs.claim_amount_numeric;

    var dt = new sn_dt.DecisionTableAPI();

    var response = dt.getDecision(
        '8641c6e37dd703107f4479dec5c54758',
        decisionInputs
    );

    if (!response) {
        throw 'No matching settlement decision was found.';
    }

    var result = response.result_elements;

    outputs.recommended_amount =
        result.u_recommended_amount.getValue();

    outputs.minimum_amount =
        result.u_minimum_amount.getValue();

    outputs.maximum_amount =
        result.u_maximum_amount.getValue();

    outputs.rationale =
        result.u_rationale.getValue();

    outputs.approval_required =
        result.u_approval_required.getValue();

})(inputs, outputs);

